        // Check if array is cyclically descending
        int c = nums[0];
        bool desc = true;
        for (int i = 0; i < n; i++) {
            if (nums[i] != ((c - i) % n + n) % n) {
                desc = false;
                break;
            }
        }
        if (desc) {
            int t = (c + 1) % n;
            best = min(best, min(t, n - t) + 1);
        }

        return best == INT_MAX ? -1 : best;
    }
};

